const out=[];
for (const q of ["Daniso Horsa","Marlon Bolaños Washed Ají Bourbon","Cloister Reserve Blend Espresso"]) {
 page.goto("https://www.coffeereview.com/?s="+encodeURIComponent(q));
 const l=page.evaluate(() => [...document.querySelectorAll("a")].map(a=>a.href).filter(h=>/coffeereview.com\/review\/[^/]+\/$/.test(h)));
 out.push(q, l.slice(0,5));
 const u=l.find(h=>/daniso|marlon|cloister/i.test(h));
 if(u){page.goto(u); out.push(page.evaluate(()=>document.body.innerText.match(/Est\. Price[^\n]*/)?.[0]));}
}
return out;
